promptAuth(channel, level, authInfo) {
  if (authInfo.flags & Ci.nsIAuthInformation.PREVIOUS_FAILED) {
    return false;
  }

  this.origin = channel.URI.prePath;
  this.authInfo = authInfo;

  const site = Services.eTLD.getSite(channel.URI);
  const password =
    !this.passwordSite ||
    site == this.passwordSite ||
    (channel.URI.schemeIs("https") &&
      site.replace(/^https:/, "http:") == this.passwordSite)
      ? this.password
      : null;

  if (!this.forcePrompt) {
    if (this.username && password) {
      authInfo.username = this.username;
      authInfo.password = password;
      this.shouldSaveAuth = this.storePasswordOverride ?? true;
      return true;
    }

    let finished = false;
    let logins;
    Services.logins
      .searchLoginsAsync({ origin: channel.URI.prePath })
      .then(result => (logins = result))
      .finally(() => (finished = true));
    Services.tm.spinEventLoopUntilOrQuit(
      "CardDAVUtils.sys.mjs:promptAuth",
      () => finished
    );
    for (const l of logins) {
      if (l.username == this.username) {
        authInfo.username = l.username;
        authInfo.password = l.password;
        return true;
      }
    }
  }

  authInfo.username = this.username;
